"use strict";(self.webpackChunkdg_knowlege_base=self.webpackChunkdg_knowlege_base||[]).push([[2578],{23895:e=>{e.exports=JSON.parse('{"tag":{"label":"Lineage","permalink":"/datagol-knowlegde-base-v1/docs/tags/lineage","allTagsPath":"/datagol-knowlegde-base-v1/docs/tags","count":14,"items":[{"id":"Data lineage/About data lineage","title":"About data lineage","description":"Data lineage is the process of tracking the origin, movement, transformation, and usage of data across an organization\'s ecosystem. It helps teams understand where data comes from, how it flows through systems, and how it changes over time.","permalink":"/datagol-knowlegde-base-v1/docs/Data lineage/about-data-lineage"},{"id":"Machine Learning/About Machine Learning","title":"About Machine Learning","description":"The ML dashboard provides a centralized interface for building predictive solutions tailored to various analytical needs. You can create the following types of models:","permalink":"/datagol-knowlegde-base-v1/docs/Machine Learning/about-machine-learning-ML"},{"id":"Machine Learning/Creating Classification model","title":"Creating Classification model","description":"From a workbook, click Actions > ML Dashboard. The ML Dashboard page is displayed.","permalink":"/datagol-knowlegde-base-v1/docs/Machine Learning/creating-classification-model"},{"id":"Machine Learning/Creating Forecasting model","title":"Creating Forecasting model","description":"From a workbook, click Actions > ML Dashboard. The ML Dashboard page is displayed.","permalink":"/datagol-knowlegde-base-v1/docs/Machine Learning/creating-forecasting-model"},{"id":"Machine Learning/Creating Regression model","title":"Creating Regression model","description":"From a workbook, click Actions > ML Dashboard. The ML Dashboard page is displayed.","permalink":"/datagol-knowlegde-base-v1/docs/Machine Learning/creating-regression-model"},{"id":"Data lineage/Data source lineage","title":"Data source lineage","description":"Data source lineage shows you all the different pipelines and workbooks that draw data from that specific source.","permalink":"/datagol-knowlegde-base-v1/docs/Data lineage/data-source-lineage"},{"id":"Reference guides/Formula reference","title":"Formula reference","description":"String functions","permalink":"/datagol-knowlegde-base-v1/docs/Reference guides/formula-reference"},{"id":"Data lineage/Impact analysis","title":"Impact analysis","description":"Impact analysis is a capability in the Data Lineage module to help you assess the downstream effects of potentially disruptive actions within the platform. This feature is designed to increase the awareness and reduce unintended consequences when altering or removing data entities.","permalink":"/datagol-knowlegde-base-v1/docs/Data lineage/impact-analysis"},{"id":"Data lineage/Managing data lineage","title":"Managing data lineage","description":"The data lineage views in DataGOL offer several features to help you manage and understand the details:","permalink":"/datagol-knowlegde-base-v1/docs/Data lineage/manage-data-lineage"},{"id":"Data lineage/Pipeline lineage","title":"Pipeline lineage","description":"Pipeline lineage shows you exactly where the data enters the pipeline, the transformations/queries it goes through within the pipeline, and where it ultimately exits (the destination data warehouse or table).","permalink":"/datagol-knowlegde-base-v1/docs/Data lineage/pipeline-data-lineage"},{"id":"Reference guides/Roles and permissions","title":"Roles and permissions","description":"| Role | Description |","permalink":"/datagol-knowlegde-base-v1/docs/Reference guides/roles-permissions"},{"id":"Reference guides/Spark exception and troubleshooting","title":"Spark exception and troubleshooting","description":"This guide aims to provide troubleshooting steps for common Spark errors encountered within the DataGOL platform, specifically related to Apache Kyuubi and Spark Driver failures.","permalink":"/datagol-knowlegde-base-v1/docs/Reference guides/spark-exception-and-troubleshooting"},{"id":"Data lineage/Workbook lineage","title":"Workbook lineage","description":"Workbook lineage traces the data back from its original source, showing any materialized views along the way.","permalink":"/datagol-knowlegde-base-v1/docs/Data lineage/workbook-lineage"},{"id":"Data Lineage/Workbook Lineage","title":"Workbook Lineage","description":"Workbook lineage traces the data back from its original source, showing any materialized views along the way.","permalink":"/datagol-knowlegde-base-v1/docs/Data Lineage/workbook-lineage"}],"unlisted":false}}')}}]);